<?php
require_once __DIR__ . '/../lib/bootstrap.php'; require_role('teacher','admin');
$uid=(int)current_user()['id'];$id=get_int('id');$section=($_GET['section']??'existing')==='bank'?'bank':'existing';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post_string('action');
 if($action==='create_exam'){$subjectId=(int)($_POST['subject_id']??0);$chapter=post_string('chapter',150);$classId=(int)($_POST['class_id']??0);$allowed=current_user()['role']==='admin';if(!$allowed){$check=db()->prepare('SELECT COUNT(*) FROM teacher_classes WHERE teacher_id=? AND class_id=?');$check->execute([$uid,$classId]);$allowed=(int)$check->fetchColumn()===1;}if(!$allowed){flash('error','شما به این کلاس منتسب نیستید.');redirect('teacher/exams.php');}$s=db()->prepare('INSERT INTO exams(subject_id,chapter,class_id,title,instructions,duration_minutes,total_score,max_attempts,score_policy,starts_at,ends_at,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$subjectId,$chapter,$classId,post_string('title',200),post_string('instructions'),max(1,(int)($_POST['duration_minutes']??30)),(float)($_POST['total_score']??20),min(10,max(1,(int)($_POST['max_attempts']??1))),in_array($_POST['score_policy']??'latest',['best','latest'],true)?$_POST['score_policy']:'latest',post_string('starts_at')?:null,post_string('ends_at')?:null,$uid]);$id=(int)db()->lastInsertId();flash('success','آزمون ایجاد شد؛ اکنون پرسش اضافه کنید.');redirect('teacher/exams.php?id='.$id);}
 if($action==='add_question'){$type=post_string('question_type');$orderStmt=db()->prepare('SELECT COALESCE(MAX(sort_order),0)+1 FROM questions WHERE exam_id=?');$orderStmt->execute([$id]);$nextOrder=(int)$orderStmt->fetchColumn();$s=db()->prepare('INSERT INTO questions(exam_id,question_text,question_type,score,sort_order,feedback,reference_answer,rubric) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$id,post_string('question_text'),$type,(float)($_POST['score']??1),$nextOrder,post_string('feedback'),post_string('reference_answer'),post_string('rubric')]);$qid=(int)db()->lastInsertId();if(in_array($type,['mcq','true_false'],true)){ $opts=$type==='true_false'?['A'=>'درست','B'=>'نادرست']:['A'=>post_string('option_a',500),'B'=>post_string('option_b',500),'C'=>post_string('option_c',500),'D'=>post_string('option_d',500)];$correct=post_string('correct_key');$n=0;foreach($opts as $k=>$v){if($v!==''){$x=db()->prepare('INSERT INTO question_options(question_id,option_text,option_key,is_correct,sort_order) VALUES(?,?,?,?,?)');$x->execute([$qid,$v,$k,$k===$correct?1:0,$n++]);}}}flash('success','پرسش افزوده شد.');redirect('teacher/exams.php?id='.$id);}
 if($action==='auto_generate'){$chapter=post_string('chapter',150);if($chapter===''){$chapterStmt=db()->prepare('SELECT chapter FROM exams WHERE id=?');$chapterStmt->execute([$id]);$chapter=(string)($chapterStmt->fetchColumn()??'');}$difficulty=post_string('difficulty');$types=['mcq','true_false','short'];$counts=['mcq'=>max(0,(int)($_POST['count_mcq']??0)),'true_false'=>max(0,(int)($_POST['count_true_false']??0)),'short'=>max(0,(int)($_POST['count_short']??0))];$pdo=db();$added=0;$orderStmt=$pdo->prepare('SELECT COALESCE(MAX(sort_order),0)+1 FROM questions WHERE exam_id=?');$orderStmt->execute([$id]);$order=(int)$orderStmt->fetchColumn();$pdo->beginTransaction();try{foreach($types as $type){$n=$counts[$type]??0;if($n<1)continue;$sql='SELECT * FROM question_bank b WHERE b.subject_id=(SELECT subject_id FROM exams WHERE id=?) AND b.is_active=1 AND COALESCE(b.chapter,"")=(SELECT COALESCE(chapter,"") FROM exams WHERE id=?) AND b.question_type=? AND NOT EXISTS (SELECT 1 FROM questions eq WHERE eq.exam_id=? AND eq.question_text=b.question_text)';$p=[$id,$id,$type,$id];if($chapter!==''){$sql.=' AND chapter LIKE ?';$p[]='%'.$chapter.'%';}if(in_array($difficulty,['easy','medium','hard'],true)){$sql.=' AND difficulty=?';$p[]=$difficulty;}$sql.=' ORDER BY RAND() LIMIT '.(int)$n;$st=$pdo->prepare($sql);$st->execute($p);foreach($st as $bank){$q=$pdo->prepare('INSERT INTO questions(exam_id,question_text,chapter,image_path,question_type,score,difficulty,tags,sort_order,reference_answer,rubric) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$id,$bank['question_text'],$bank['chapter']??null,$bank['image_path']??null,$bank['question_type'],$bank['score'],$bank['difficulty']??'medium',$bank['tags']??null,$order++,$bank['reference_answer'],$bank['rubric']]);$new=(int)$pdo->lastInsertId();$os=$pdo->prepare('SELECT * FROM question_bank_options WHERE bank_question_id=? ORDER BY sort_order,id');$os->execute([$bank['id']]);$oi=$pdo->prepare('INSERT INTO question_options(question_id,option_text,image_path,option_key,is_correct,sort_order) VALUES(?,?,?,?,?,?)');foreach($os as $o)$oi->execute([$new,$o['option_text'],$o['image_path']??null,$o['option_key'],$o['is_correct'],$o['sort_order']]);$added++;}}$pdo->commit();flash('success',$added.' سؤال به‌صورت خودکار اضافه شد.');}catch(Throwable $e){$pdo->rollBack();flash('error','تولید خودکار انجام نشد: '.$e->getMessage());}redirect('teacher/exams.php?id='.$id);} if(in_array($action,['delete_question','update_question_score','move_question'],true)){ $qId=(int)($_POST['question_id']??0);$check=db()->prepare('SELECT e.status,q.sort_order FROM questions q JOIN exams e ON e.id=q.exam_id WHERE q.id=? AND q.exam_id=?');$check->execute([$qId,$id]);$target=$check->fetch();if(!$target||$target['status']!=='draft'){flash('error','این عملیات فقط برای آزمون پیش‌نویس مجاز است.');}else if($action==='delete_question'){$pdo=db();$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM question_options WHERE question_id=?')->execute([$qId]);$pdo->prepare('DELETE FROM questions WHERE id=? AND exam_id=?')->execute([$qId,$id]);$pdo->commit();flash('success','پرسش از آزمون حذف شد.');}catch(Throwable $e){$pdo->rollBack();flash('error','حذف پرسش انجام نشد.');}}else if($action==='update_question_score'){$score=max(0.01,(float)($_POST['score']??0));$s=db()->prepare('UPDATE questions SET score=? WHERE id=? AND exam_id=?');$s->execute([$score,$qId,$id]);flash('success','نمرهٔ پرسش تغییر کرد.');}else{$direction=post_string('direction');$cmp=$direction==='up'?'<':'>';$sort=$direction==='up'?'DESC':'ASC';$neighbor=db()->prepare("SELECT id,sort_order FROM questions WHERE exam_id=? AND sort_order $cmp ? ORDER BY sort_order $sort LIMIT 1");$neighbor->execute([$id,$target['sort_order']]);$other=$neighbor->fetch();if($other){$pdo=db();$pdo->beginTransaction();$tmp=-1;$pdo->prepare('UPDATE questions SET sort_order=? WHERE id=?')->execute([$tmp,$qId]);$pdo->prepare('UPDATE questions SET sort_order=? WHERE id=?')->execute([$target['sort_order'],$other['id']]);$pdo->prepare('UPDATE questions SET sort_order=? WHERE id=?')->execute([$other['sort_order'],$qId]);$pdo->commit();flash('success','ترتیب پرسش تغییر کرد.');}}redirect('teacher/exams.php?id='.$id);} if($action==='publish'){$countStmt=db()->prepare('SELECT COUNT(*) FROM questions WHERE exam_id=?');$countStmt->execute([$id]);$count=(int)$countStmt->fetchColumn();if($count<1)flash('error','آزمون بدون پرسش قابل انتشار نیست.');else{$s=db()->prepare('UPDATE exams SET status="published" WHERE id=?');$s->execute([$id]);$students=db()->prepare('SELECT cs.student_id,e.title FROM class_students cs JOIN exams e ON e.class_id=cs.class_id WHERE e.id=?');$students->execute([$id]);$studentRows=$students->fetchAll();if($studentRows){$examNotice=$studentRows[0];foreach($studentRows as $student)notify_user((int)$student['student_id'],'آزمون جدید منتشر شد','آزمون «'.$examNotice['title'].'» برای شما فعال شد.','student/exam.php?id='.$id,'exam_published');}flash('success','آزمون منتشر شد و اعلان آن برای دانش‌آموزان ارسال شد.');}redirect('teacher/exams.php?id='.$id);}}
$subjects=db()->query("SELECT id,title FROM subjects WHERE is_active=1 AND (created_by=$uid OR ".(current_user()['role']==='admin'?'1=1':'0=1').") ORDER BY title")->fetchAll();if(current_user()['role']==='admin'){$classes=db()->query('SELECT id,title FROM classes ORDER BY title')->fetchAll();}else{$classStmt=db()->prepare('SELECT c.id,c.title FROM classes c JOIN teacher_classes tc ON tc.class_id=c.id WHERE tc.teacher_id=? ORDER BY c.title');$classStmt->execute([$uid]);$classes=$classStmt->fetchAll();}$exam=null;$questions=[];if($id){$s=db()->prepare('SELECT e.*,s.title subject_title,c.title class_title FROM exams e JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id WHERE e.id=?');$s->execute([$id]);$exam=$s->fetch();$s=db()->prepare('SELECT q.*,GROUP_CONCAT(CONCAT(o.option_key,": ",o.option_text) ORDER BY o.sort_order SEPARATOR " | ") options_text FROM questions q LEFT JOIN question_options o ON o.question_id=q.id WHERE q.exam_id=? GROUP BY q.id ORDER BY q.sort_order');$s->execute([$id]);$questions=$s->fetchAll();$capacity=['mcq'=>0,'true_false'=>0,'short'=>0];$cs=db()->prepare('SELECT b.question_type,COUNT(*) total FROM question_bank b WHERE b.subject_id=? AND b.is_active=1 AND COALESCE(b.chapter,"")=COALESCE(?, "") AND NOT EXISTS (SELECT 1 FROM questions eq WHERE eq.exam_id=? AND eq.question_text=b.question_text) GROUP BY b.question_type');$cs->execute([$exam['subject_id'],$exam['chapter']??'',$id]);foreach($cs as $row)$capacity[$row['question_type']]=(int)$row['total'];}$title='مدیریت آزمون';require __DIR__.'/../partials/header.php';?><h1>مدیریت آزمون</h1><?php if(!$exam):?><div class="card"><h2>آزمون جدید</h2><form method="post" class="grid grid-2"><?=csrf_field()?><input type="hidden" name="action" value="create_exam"><div class="form-group"><label>درس</label><select name="subject_id" required><option value="">انتخاب کنید</option><?php foreach($subjects as $s):?><option value="<?=$s['id']?>" <?=get_int('subject_id')===$s['id']?'selected':''?>><?=e($s['title'])?></option><?php endforeach;?></select></div><div class="form-group"><label>کلاس</label><select name="class_id" required><option value="">انتخاب کنید</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['title'])?></option><?php endforeach;?></select></div><div class="form-group"><label>عنوان آزمون</label><input name="title" required></div><div class="form-group"><label>پودمان / فصل آزمون</label><input name="chapter" maxlength="150" placeholder="مثلاً پودمان ۲ - الگوریتم" required><small class="muted">سؤال‌های بانک در این آزمون بر اساس همین پودمان فیلتر می‌شوند.</small></div><div class="form-group"><label>مدت به دقیقه</label><input type="number" name="duration_minutes" value="30" min="1"></div><div class="form-group"><label>نمره کل</label><input type="number" step="0.01" name="total_score" value="20"></div><div class="form-group"><label>تعداد تلاش مجاز</label><input type="number" name="max_attempts" value="1" min="1" max="10"><small class="muted">بین ۱ تا ۱۰ تلاش</small></div><div class="form-group"><label>ملاک نمره نهایی</label><select name="score_policy"><option value="latest">آخرین تلاش</option><option value="best">بهترین تلاش</option></select></div><div class="form-group"><label>زمان شروع (اختیاری)</label><input type="datetime-local" name="starts_at"></div><div class="form-group"><label>زمان پایان (اختیاری)</label><input type="datetime-local" name="ends_at"></div><div class="form-group"><label>توضیحات</label><textarea name="instructions"></textarea></div><button class="btn btn-primary">ایجاد آزمون</button></form></div><?php else:?><div class="card"><h2><?=e($exam['title'])?></h2><p><?=e($exam['subject_title'])?> — <?=e($exam['class_title'])?> — وضعیت: <span class="badge"><?=e($exam['status'])?></span> | تلاش مجاز: <?=e((string)($exam['max_attempts']??1))?> | ملاک نمره: <?=($exam['score_policy']??'latest')==='best'?'بهترین':'آخرین'?></p><?php if($exam['status']==='draft'):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="publish"><button class="btn btn-success">انتشار آزمون</button></form><?php endif;?><a class="btn btn-light" target="_blank" href="<?=e(url('teacher/preview_exam.php?id='.$id))?>">پیش‌نمایش آزمون</a><a class="btn btn-light" href="<?=e(url('teacher/review_short_answers.php?exam_id='.$id))?>">بررسی پاسخ کوتاه</a><a class="btn btn-light" href="<?=e(url('teacher/exam_report.php?exam_id='.$eid))?>">گزارش آزمون</a><a class="btn btn-light" href="<?=e(url('teacher/attempts.php?exam_id='.$id))?>">مدیریت تلاش‌ها</a><a class="btn btn-primary" href="<?=e(url('teacher/import_questions.php?exam_id='.$id))?>">ورود گروهی پرسش‌ها از Word</a><a class="btn btn-primary" href="<?=e(url('teacher/question_bank.php?exam_id='.$id))?>">بانک سؤال</a></div><nav class="bank-section-nav exam-section-nav" aria-label="بخش‌های آزمون"><a href="<?=e(url('teacher/exams.php?id='.$id.'&section=existing'))?>" class="bank-section-link <?=$section==='existing'?'active':''?>">سؤالات موجود در آزمون</a><a href="<?=e(url('teacher/exams.php?id='.$id.'&section=bank'))?>" class="bank-section-link <?=$section==='bank'?'active':''?>">افزودن از بانک سؤال</a></nav><?php if($section==='bank'):?><div class="card"><p class="muted">از این بخش می‌توانید سؤال‌های بانک را به آزمون اضافه کنید. برای دیدن سؤال‌های فعلی آزمون، تب «سؤالات موجود در آزمون» را انتخاب کنید.</p><a class="btn btn-light" href="<?=e(url('teacher/exams.php?id='.$id.'&section=existing'))?>">بازگشت به سؤالات آزمون</a></div><div class="card"><h2>ظرفیت باقی‌مانده بانک سؤال</h2><p class="muted">پودمان آزمون: <strong><?=e($exam['chapter']??'بدون پودمان')?></strong> — فقط سؤال‌های همین درس و پودمان محاسبه می‌شوند.</p><div class="grid grid-3"><div class="stat-card"><strong><?=e((string)$capacity['mcq'])?></strong><span>تستی</span></div><div class="stat-card"><strong><?=e((string)$capacity['true_false'])?></strong><span>صحیح/غلط</span></div><div class="stat-card"><strong><?=e((string)$capacity['short'])?></strong><span>پاسخ کوتاه</span></div></div></div><div class="card"><h2>تولید خودکار از بانک سؤال</h2><p class="muted">سؤال‌ها به آزمون پیش‌نویس اضافه می‌شوند و قبل از انتشار قابل بازبینی هستند.</p><form method="post" class="grid grid-2"><?=csrf_field()?><input type="hidden" name="action" value="auto_generate"><div class="form-group"><label>فصل / مبحث اختیاری</label><input name="chapter" placeholder="مثلاً فصل دوم"></div><div class="form-group"><label>سطح دشواری</label><select name="difficulty"><option value="">همهٔ سطوح</option><option value="easy">آسان</option><option value="medium">متوسط</option><option value="hard">سخت</option></select></div><div class="form-group"><label>تعداد تستی</label><input type="number" name="count_mcq" value="0" min="0"></div><div class="form-group"><label>تعداد صحیح/غلط</label><input type="number" name="count_true_false" value="0" min="0"></div><div class="form-group"><label>تعداد پاسخ کوتاه</label><input type="number" name="count_short" value="0" min="0"></div><button class="btn btn-success">تولید و افزودن به آزمون</button></form></div><div class="card"><h2>افزودن پرسش دستی</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add_question"><div class="form-group"><label>متن پرسش</label><textarea name="question_text" required></textarea></div><div class="grid grid-2"><div class="form-group"><label>نوع</label><select name="question_type"><option value="mcq">چهارگزینه‌ای</option><option value="true_false">درست / نادرست</option><option value="short">تشریحی</option></select></div><div class="form-group"><label>نمره</label><input name="score" type="number" step="0.01" value="1"></div><div class="form-group"><label>پاسخ مرجع (برای سؤال تشریحی)</label><textarea name="reference_answer" placeholder="پاسخ کامل یا نمونهٔ مورد انتظار را بنویسید..."></textarea></div><div class="form-group"><label>معیارهای نمره‌دهی محلی</label><textarea name="rubric" placeholder="هر معیار در یک خط با قالب: عبارت کلیدی|نمره&#10;مثال: تعریف صحیح|1&#10;مثال اول|1"></textarea></div></div><div class="grid grid-2"><div class="form-group"><label>گزینه A</label><input name="option_a"></div><div class="form-group"><label>گزینه B</label><input name="option_b"></div><div class="form-group"><label>گزینه C</label><input name="option_c"></div><div class="form-group"><label>گزینه D</label><input name="option_d"></div><div class="form-group"><label>کلید پاسخ صحیح</label><select name="correct_key"><option value="A">A</option><option value="B">B</option><option value="C">C</option><option value="D">D</option></select></div></div><button class="btn btn-primary">افزودن پرسش</button></form></div><?php endif;?><div class="card"><h2>پرسش‌های ثبت‌شده</h2><?php if($section==='existing'):?><?php foreach($questions as $i=>$q):?><div class="question"><strong><?=($i+1).'. '.e($q['question_text'])?></strong><div class="muted">نوع: <?=e($q['question_type'])?> | نمره: <?=e($q['score'])?> | <?=e($q['options_text']??'')?></div><?php if($exam['status']==='draft'):?><div class="actions"><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="update_question_score"><input type="hidden" name="question_id" value="<?=$q['id']?>"><input type="number" name="score" step="0.01" min="0.01" value="<?=e($q['score'])?>" style="width:90px"><button class="btn btn-sm btn-light">ذخیره نمره</button></form><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="move_question"><input type="hidden" name="question_id" value="<?=$q['id']?>"><input type="hidden" name="direction" value="up"><button class="btn btn-sm btn-light">↑</button></form><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="move_question"><input type="hidden" name="question_id" value="<?=$q['id']?>"><input type="hidden" name="direction" value="down"><button class="btn btn-sm btn-light">↓</button></form><form method="post" style="display:inline" onsubmit="return confirm('این پرسش از آزمون حذف شود؟')"><?=csrf_field()?><input type="hidden" name="action" value="delete_question"><input type="hidden" name="question_id" value="<?=$q['id']?>"><button class="btn btn-sm btn-danger">حذف</button></form></div><?php endif;?></div><?php endforeach;?></div><?php endif;?><?php endif;?><?php require __DIR__.'/../partials/footer.php'; ?>
